from collections import deque, defaultdict

def min_moves_to_reach_end(grid):
    if not grid or not grid[0]:
        return -1
    m, n = len(grid), len(grid[0])
    if grid[0][0] == '#' or grid[m - 1][n - 1] == '#':
        return -1

    portals = defaultdict(list)
    for r in range(m):
        for c in range(n):
            if grid[r][c].isupper():
                portals[grid[r][c]].append((r, c))

    dist = [[-1] * n for _ in range(m)]
    dist[0][0] = 0
    used = set()
    dq = deque([(0, 0)])

    while dq:
        r, c = dq.popleft()
        d = dist[r][c]
        if (r, c) == (m - 1, n - 1):
            return d
        ch = grid[r][c]
        if ch.isupper() and ch not in used:
            used.add(ch)
            for pr, pc in portals[ch]:
                if dist[pr][pc] == -1 or dist[pr][pc] > d:
                    dist[pr][pc] = d
                    dq.appendleft((pr, pc))
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] != '#':
                if dist[nr][nc] == -1 or dist[nr][nc] > d + 1:
                    dist[nr][nc] = d + 1
                    dq.append((nr, nc))
    return -1
